#include "th03/audio/pmd_opna.hpp"
#include "sound_effects.hpp"
#include <filesystem>
#include <fstream>
#include <vector>
#include <iostream>
std::vector<std::byte> read(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("Missing asset");auto n=f.tellg();std::vector<std::byte>b(static_cast<std::size_t>(n));f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),n);return b;}
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("need assets");auto root=std::filesystem::path(argv[1]);auto bank=read(root/"HUUMA.EFC"),song=read(root/"OP.M");unsigned checks=0;auto check=[&](bool v){++checks;if(!v)throw std::runtime_error("EFC failed check="+std::to_string(checks));};for(unsigned id=0;id<19;++id){auto e=th03::audio::PmdOpnaEngine::create({.input_clock_hz=7987200,.fidelity=th03::audio::PmdOpnaFidelity::minimum});check(bool(e));auto loaded=e->load_effect_bank(bank);if(!loaded){std::cerr<<"bank_error="<<int(loaded.error().code)<<" bytes="<<loaded.error().supplied_size<<'\n';check(false);}check(bool(e->load_song(song)));check(bool(e->set_user_volumes(0,25)));check(bool(e->play()));e->stop();check(bool(e->play_effect(static_cast<std::uint8_t>(id))));std::vector<th03::audio::PmdOpnaStereoSample> pcm(55467);e->render_native(pcm);std::uint64_t energy=0;for(auto s:pcm)energy+=std::uint64_t(std::abs(std::int64_t(s.left)))+std::uint64_t(std::abs(std::int64_t(s.right)));std::cout<<"se="<<id<<" energy="<<energy<<'\n';if(id>=2)check(energy>0);}
for(unsigned a=0;a<19;++a)for(unsigned b=0;b<19;++b){soew::SoundEffects scheduler;scheduler.request(a);auto first=scheduler.update();check(first&&*first==a);scheduler.request(b);if(soew::SoundEffects::priorities[b]>=soew::SoundEffects::priorities[a]||scheduler.current==b){auto second=scheduler.update();check(second&&*second==b);}}std::cout<<"sfx_checks="<<checks<<" failures=0\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
